181		d, e := sql.Open("postgres", url)
182		if e != nil {
183			return nil, e
184		}
185		d.SetMaxOpenConns(16)
186		return &Store{d}, d.Ping()
187	}
188	func (s *Store) Rows(query string, args ...any) ([]map[string]any, error) {
189		r, e := s.DB.Query(query, args...)
190		if e != nil {
191			return nil, e
192		}
193		defer r.Close()
194		cols, e := r.Columns()
195		if e != nil {
196			return nil, e
197		}
198		out := []map[string]any{}
199		for r.Next() {
200			vals := make([]any, len(cols))
201			ptr := make([]any, len(cols))
202			for i := range vals {
203				ptr[i] = &vals[i]
204			}
205			if e = r.Scan(ptr...); e != nil {
206				return nil, e
207			}
208			m := map[string]any{}
209			for i, k := range cols {
210				v := vals[i]
211				if b, ok := v.([]byte); ok {
212					if k == "payload" || k == "result" || k == "body" {
213						var j any
214						if json.Unmarshal(b, &j) == nil {
215							v = j
216						} else {
217							v = string(b)
218						}
219					} else {
220						v = string(b)
221					}
222				}
223				m[k] = v
224			}
225			out = append(out, m)
226		}
227		return out, r.Err()
228	}
229	func (s *Store) One(query string, args ...any) (map[string]any, error) {
230		r, e := s.Rows(query, args...)
231		if e != nil {
232			return nil, e
233		}
234		if len(r) == 0 {
235			return nil, sql.ErrNoRows
236		}
237		return r[0], nil
238	}
