247	type QueueInput struct {
248		Name           string  `json:"name"`
249		LeaseSeconds   int     `json:"lease_seconds"`
250		MaxAttempts    int     `json:"max_attempts"`
251		RetentionHours float64 `json:"retention_hours"`
252		Backoff        struct {
253			Kind        string `json:"kind"`
254			BaseSeconds int    `json:"base_seconds"`
