285		v, e := s.S.Rows(`SELECT * FROM queues WHERE namespace_id=$1 ORDER BY id`, ident(r).Namespace)
286		output(w, map[string]any{"queues": v}, e)
287	}
288	func (s *Server) getQueue(w http.ResponseWriter, r *http.Request) {
289		q, ok := s.queueOrError(w, r)
290		if ok {
291			write(w, 200, q)
292		}
293	}
294	func (s *Server) patchQueue(w http.ResponseWriter, r *http.Request) {
295		q, ok := s.queueOrError(w, r)
296		if !ok {
297			return
298		}
299		var in struct {
300			LeaseSeconds   *int     `json:"lease_seconds"`
301			MaxAttempts    *int     `json:"max_attempts"`
302			RetentionHours *float64 `json:"retention_hours"`
303			Webhook        *struct {
304				URL    string `json:"url"`
305				Secret string `json:"secret"`
306			} `json:"webhook"`
307		}
308		if !decode(w, r, &in) {
309			return
310		}
311		if in.LeaseSeconds != nil && *in.LeaseSeconds < 1 {
312			fail(w, 400, "invalid_queue", "lease_seconds must be positive")
313			return
314		}
315		url, secret := q["webhook_url"], q["webhook_secret"]
316		if in.Webhook != nil {
317			url = in.Webhook.URL
318			secret = in.Webhook.Secret
319		}
320		v, e := s.S.One(`UPDATE queues SET lease_seconds=COALESCE($2,lease_seconds),max_attempts=COALESCE($3,max_attempts),retention_hours=COALESCE($4,retention_hours),webhook_url=$5,webhook_secret=$6 WHERE id=$1 RETURNING *`, q["id"], in.LeaseSeconds, in.MaxAttempts, in.RetentionHours, url, secret)
321		output(w, v, e)
