139	func (s *Server) deleteJob(w http.ResponseWriter, r *http.Request) {
140		res, e := s.S.DB.Exec(`DELETE FROM jobs WHERE id=$1 AND state IN ('succeeded','dead','cancelled')`, num(r, "id"))
141		if e = jobs.Changed(res, e); e != nil {
142			fail(w, 409, "state_conflict", e)
143			return
144		}
145		write(w, 204, nil)
146	}
147	func (s *Server) jobVerb(w http.ResponseWriter, r *http.Request) {
148		id := num(r, "id")
149		now := time.Now()
150		var e error
151		switch r.PathValue("verb") {
152		case "cancel":
153			e = s.Jobs.Cancel(id, now)
154		case "retry":
155			e = s.Jobs.Retry(id, now)
156		case "ack", "nack", "heartbeat":
157			var in struct {
158				LeaseToken    string `json:"lease_token"`
159				Result        any    `json:"result"`
160				Error         string `json:"error"`
161				Retry         *bool  `json:"retry"`
162				DelaySeconds  *int   `json:"delay_seconds"`
163				ExtendSeconds int    `json:"extend_seconds"`
164			}
165			if !decode(w, r, &in) {
166				return
167			}
168			switch r.PathValue("verb") {
169			case "ack":
170				e = s.Jobs.Ack(id, in.LeaseToken, in.Result, now)
171			case "nack":
172				retry := true
173				if in.Retry != nil {
174					retry = *in.Retry
175				}
176				e = s.Jobs.Nack(id, in.LeaseToken, in.Error, retry, in.DelaySeconds, now)
177			case "heartbeat":
178				if in.ExtendSeconds < 1 {
179					fail(w, 400, "invalid_extension", "positive extension required")
180					return
181				}
182				e = s.Jobs.Heartbeat(id, in.LeaseToken, in.ExtendSeconds, now)
183			}
184		default:
185			fail(w, 404, "not_found", "unknown operation")
186			return
187		}
188		if e != nil {
189			fail(w, 409, "state_conflict", e)
190			return
191		}
192		write(w, 200, map[string]any{"ok": true})
193	}
