198		}
199		if !decode(w, r, &in) {
200			return
201		}
202		if in.Name == "" || len(in.Kinds) == 0 {
203			fail(w, 400, "invalid_worker", "name and kinds required")
204			return
205		}
206		token := jobs.Token()
207		var id int64
208		e := s.S.DB.QueryRow(`INSERT INTO workers(namespace_id,name,kinds,token,last_seen_at) VALUES($1,$2,$3,$4,$5) RETURNING id`, ident(r).Namespace, in.Name, pq.Array(in.Kinds), token, time.Now()).Scan(&id)
209		if e != nil {
210			fail(w, 500, "database_error", e)
