222		res, e := tx.Exec(`DELETE FROM workers WHERE id=$1 AND namespace_id=$2`, num(r, "id"), ident(r).Namespace)
223		if e = jobs.Changed(res, e); e != nil {
224			fail(w, 404, "worker_not_found", e)
225			return
226		}
227		_, e = tx.Exec(`UPDATE jobs SET state='queued',lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE leased_by=$1 AND state='leased'`, num(r, "id"))
228		if e == nil {
229			e = tx.Commit()
230		}
231		output(w, map[string]any{"ok": true}, e)
