 36	package jobs
 37	
 38	import (
 39		"crypto/rand"
 40		"database/sql"
 41		"encoding/hex"
 42		"encoding/json"
 43		"fmt"
 44		"github.com/lib/pq"
 45		"queuelet/internal/store"
 46		"time"
 47	)
 48	
 49	type Service struct{ S *store.Store }
 50	
 51	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
 52	func Backoff(kind string, base, attempt int) time.Duration {
 53		if kind == "linear" {
 54			return time.Duration(base*attempt) * time.Second
 55		}
 56		return time.Duration(base) * time.Second * time.Duration(uint64(1)<<uint(attempt-1))
 57	}
 58	
 59	const LeaseOrder = "priority DESC, created_at"
 60	
 61	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
 62		tx, e := j.S.DB.Begin()
 63		if e != nil {
 64			return nil, e
 65		}
 66		defer tx.Rollback()
 67		var sec int
 68		var paused bool
 69		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
 70			return nil, e
 71		}
 72		if paused {
 73			return []map[string]any{}, nil
 74		}
 75		var kinds pq.StringArray
 76		if e = tx.QueryRow(`SELECT kinds FROM workers WHERE id=$1`, w).Scan(&kinds); e != nil {
 77			return nil, e
 78		}
 79		rows, e := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state='queued' AND kind=ANY($2) ORDER BY `+LeaseOrder+` LIMIT $3 FOR UPDATE SKIP LOCKED`, q, kinds, max)
 80		if e != nil {
 81			return nil, e
 82		}
 83		ids := []int64{}
 84		for rows.Next() {
 85			var id int64
 86			rows.Scan(&id)
 87			ids = append(ids, id)
 88		}
 89		rows.Close()
 90		out := []map[string]any{}
 91		for _, id := range ids {
 92			token := Token()
 93			var payload []byte
 94			var kind string
 95			var attempt int
 96			e = tx.QueryRow(`UPDATE jobs SET state='leased',leased_by=$2,lease_token=$3,lease_expires_at=$4 WHERE id=$1 RETURNING kind,payload,attempts+1`, id, w, token, now.Add(time.Duration(sec)*time.Second)).Scan(&kind, &payload, &attempt)
 97			if e != nil {
 98				return nil, e
 99			}
100			out = append(out, map[string]any{"id": id, "kind": kind, "payload": json.RawMessage(payload), "attempt": attempt, "lease_token": token, "lease_expires_at": now.Add(time.Duration(sec) * time.Second)})
101		}
102		return out, tx.Commit()
103	}
104	func (j *Service) Notify(id int64, now time.Time) error {
105		var url, secret, state, errtext string
106		var result []byte
107		e := j.S.DB.QueryRow(`SELECT q.webhook_url,q.webhook_secret,j.state,COALESCE(j.result,'null'),j.last_error FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id).Scan(&url, &secret, &state, &result, &errtext)
108		if e != nil {
109			return e
110		}
111		if url == "" {
112			return nil
113		}
114		r := string(result)
115		if len(r) > 1024 {
116			r = r[:1024]
117		}
118		if len(errtext) > 256 {
119			errtext = errtext[:256]
120		}
121		body, _ := json.Marshal(map[string]any{"job_id": id, "state": state, "result": r, "last_error": errtext})
122		_, e = j.S.DB.Exec(`INSERT INTO webhook_outbox(job_id,url,secret,body,next_at) VALUES($1,$2,$3,$4,$5)`, id, url, secret, string(body), now)
123		return e
124	}
125	func (j *Service) Heartbeat(id int64, token string, seconds int, now time.Time) error {
126		r, e := j.S.DB.Exec(`UPDATE jobs SET lease_expires_at=$3 WHERE id=$1 AND lease_token=$2 AND state='leased'`, id, token, now.Add(time.Duration(seconds)*time.Second))
127		return Changed(r, e)
128	}
129	func Changed(r sql.Result, e error) error {
130		if e != nil {
131			return e
132		}
133		n, e := r.RowsAffected()
134		if e != nil {
135			return e
136		}
137		if n == 0 {
138			return fmt.Errorf("state conflict")
139		}
140		return nil
141	}
