144	import (
145		"testing"
146		"time"
147	)
148	
149	func TestBackoff(t *testing.T) {
150		for _, tc := range []struct {
151			kind          string
152			base, n, want int
153		}{{"exponential", 5, 1, 5}, {"exponential", 5, 2, 10}, {"exponential", 5, 3, 20}, {"linear", 5, 1, 5}, {"linear", 5, 2, 10}, {"linear", 5, 3, 15}, {"linear", 0, 2, 0}, {"exponential", 1, 4, 8}} {
154			t.Run(tc.kind+time.Duration(tc.n).String(), func(t *testing.T) {
155				if got := Backoff(tc.kind, tc.base, tc.n); got != time.Duration(tc.want)*time.Second {
156					t.Fatalf("got %s", got)
157				}
158			})
159		}
160	}
161	func TestToken(t *testing.T) {
162		a, b := Token(), Token()
163		if len(a) != 32 || a == b {
164			t.Fatal("tokens must be distinct 128 bit values")
165		}
166	}
