203	import "time"
204	
205	func (j *Service) Cancel(id int64, now time.Time) error {
206		r, e := j.S.DB.Exec(`UPDATE jobs SET state='cancelled',finished_at=$2 WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled')`, id, now)
207		if e = Changed(r, e); e != nil {
208			return e
209		}
210		return j.Notify(id, now)
211	}
212	func (j *Service) Retry(id int64, now time.Time) error {
213		r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',attempts=0,run_at=$2,finished_at=NULL WHERE id=$1`, id, now)
214		return Changed(r, e)
215	}
216	package stats
217	
218	import (
219		"queuelet/internal/store"
220		"time"
221	)
222	
223	func Read(s *store.Store, where string, arg any, now time.Time) (map[string]any, error) {
224		rows, e := s.Rows(`SELECT state,count(*) AS count FROM jobs WHERE `+where+`=$1 GROUP BY state`, arg)
225		if e != nil {
226			return nil, e
227		}
228		m := map[string]any{"queued": int64(0), "leased": int64(0), "scheduled": int64(0), "retry_wait": int64(0), "succeeded": int64(0), "dead": int64(0), "cancelled": int64(0)}
229		for _, r := range rows {
230			m[r["state"].(string)] = r["count"]
231		}
232		m["queued"] = m["queued"].(int64) + m["scheduled"].(int64) + m["retry_wait"].(int64)
233		var age float64
234		e = s.DB.QueryRow(`SELECT COALESCE(GREATEST(0,EXTRACT(EPOCH FROM ($2::timestamptz-min(run_at)))),0) FROM jobs WHERE `+where+`=$1 AND state IN ('queued','scheduled','retry_wait')`, arg, now).Scan(&age)
235		m["oldest_queued_age"] = age
236		var n int
237		e2 := s.DB.QueryRow(`SELECT count(*) FROM jobs WHERE `+where+`=$1 AND state='succeeded' AND finished_at >= $2`, arg, now.Add(-time.Hour)).Scan(&n)
238		m["throughput_last_hour"] = n
239		if e != nil {
240			return nil, e
241		}
242		return m, e2
243	}

