173	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
174		var attempts, max, base int
175		var kind string
176		e := j.S.DB.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id).Scan(&attempts, &max, &kind, &base)
177		if e != nil {
178			return e
179		}
180		state := "retry_wait"
181		if !retry || attempts > max {
182			state = "dead"
183		}
184		wait := Backoff(kind, base, attempts)
185		if delay != nil {
186			wait = time.Duration(*delay) * time.Second
187		}
188		_, e = j.S.DB.Exec(`UPDATE jobs SET state=$2,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
189		if e != nil {
190			return e
191		}
192		_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,attempts,leased_by,$2,$2,'failed',$3 FROM jobs WHERE id=$1`, id, now, message)
193		if e != nil {
194			return e
195		}
196		if state == "dead" {
197			return j.Notify(id, now)
198		}
199		return nil
200	}
