121	package schedule
122	
123	import (
124		"fmt"
125		"github.com/robfig/cron/v3"
126		"queuelet/internal/store"
127		"time"
128	)
129	
130	var parser = cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow)
131	
132	func Next(expression, zone string, offset int, after time.Time) (time.Time, error) {
133		s, e := parser.Parse(expression)
134		if e != nil {
135			return time.Time{}, e
136		}
137		return s.Next(after.In(time.FixedZone(zone, offset))), nil
138	}
139	func Offset(zone string, now time.Time) (int, error) {
140		loc, e := time.LoadLocation(zone)
141		if e != nil {
142			return 0, e
143		}
144		_, offset := now.In(loc).Zone()
145		return offset, nil
146	}
147	func Fire(s *store.Store, now time.Time) error {
148		rows, e := s.Rows(`SELECT * FROM schedules WHERE next_run_at <= $1 ORDER BY id`, now)
149		if e != nil {
150			return e
151		}
152		for _, r := range rows {
153			q, e := s.One(`SELECT * FROM queues WHERE id=$1`, r["queue_id"])
154			if e != nil {
155				continue
156			}
157			if q["paused"].(bool) {
158				continue
159			}
160			next := r["next_run_at"].(time.Time)
161			for !next.After(now) {
162				payload := r["payload"]
163				b := JSON(payload)
164				_, e = s.DB.Exec(`INSERT INTO jobs(queue_id,namespace_id,kind,payload,priority,state,run_at,max_attempts,created_at) VALUES($1,$2,$3,$4,5,'queued',$5,$6,$7)`, r["queue_id"], r["namespace_id"], r["kind"], b, next, q["max_attempts"], now)
165				if e != nil {
166					return e
167				}
168				following, e := Next(r["cron"].(string), r["timezone"].(string), int(r["zone_offset"].(int64)), next)
169				if e != nil {
170					return e
171				}
172				if !following.After(next) {
173					return fmt.Errorf("schedule cannot advance")
174				}
175				_, e = s.DB.Exec(`UPDATE schedules SET last_run_at=$2,next_run_at=$3 WHERE id=$1`, r["id"], next, following)
176				if e != nil {
177					return e
178				}
179				next = following
180			}
181		}
182		return nil
183	}
