191	func TestNext(t *testing.T) {
192		base := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
193		for _, tc := range []struct {
194			cron string
195			want time.Duration
196		}{{"* * * * *", time.Minute}, {"*/5 * * * *", 5 * time.Minute}, {"0 * * * *", time.Hour}} {
197			t.Run(tc.cron, func(t *testing.T) {
198				n, e := Next(tc.cron, "UTC", 0, base)
199				if e != nil || n.Sub(base) != tc.want {
200					t.Fatalf("%v %v", n, e)
201				}
202			})
203		}
204	}
205	func TestInvalidCron(t *testing.T) {
206		if _, e := Next("wrong", "UTC", 0, time.Now()); e == nil {
207			t.Fatal("invalid cron accepted")
208		}
209	}
