230	func Ship(s *store.Store, now time.Time) error {
231		rows, e := s.Rows(`SELECT * FROM webhook_outbox WHERE delivered_at IS NULL AND next_at <= $1 ORDER BY id LIMIT 20`, now)
232		if e != nil {
233			return e
234		}
235		for _, r := range rows {
236			body, _ := json.Marshal(r["body"])
237			pretty, _ := json.MarshalIndent(r["body"], "", "  ")
238			mac := hmac.New(sha256.New, []byte(r["secret"].(string)))
239			mac.Write(pretty)
240			req, e := http.NewRequest("POST", r["url"].(string), bytes.NewReader(body))
241			if e != nil {
242				return e
243			}
244			req.Header.Set("Content-Type", "application/json")
245			req.Header.Set("X-Queuelet-Signature", hex.EncodeToString(mac.Sum(nil)))
246			resp, e := (&http.Client{Timeout: 2 * time.Second}).Do(req)
247			if e != nil {
248				_, e = s.DB.Exec(`UPDATE webhook_outbox SET attempts=attempts+1,next_at=$2 WHERE id=$1`, r["id"], now.Add(5*time.Second))
249				if e != nil {
250					return e
251				}
252				continue
253			}
254			io.Copy(io.Discard, resp.Body)
255			resp.Body.Close()
256			log.Printf("webhook delivered status=%d", resp.StatusCode)
257			_, e = s.DB.Exec(`UPDATE webhook_outbox SET delivered_at=$2,attempts=attempts+1 WHERE id=$1`, r["id"], now)
258			if e != nil {
259				return e
260			}
261		}
262		return nil
263	}
264	package main
265	
266	import (
267		"crypto/hmac"
268		"crypto/sha256"
269		"encoding/hex"
270		"encoding/json"
271		"io"
272		"log"
273		"net/http"
274		"os"
275		"sync"
276		"time"
277	)
278	
279	func main() {
280		var mu sync.Mutex
281		mode := "ok"
282		records := []map[string]any{}
283		secret := os.Getenv("WEBHOOK_SECRET")
284		if secret == "" {
285			secret = "report-secret"
286		}
287		m := http.NewServeMux()
288		m.HandleFunc("/admin/mode", func(w http.ResponseWriter, r *http.Request) {
289			mu.Lock()
290			defer mu.Unlock()
291			if r.Method == "POST" {
292				var in struct {
293					Mode string `json:"mode"`
294				}
295				json.NewDecoder(r.Body).Decode(&in)
296				switch in.Mode {
297				case "ok", "500", "slow", "timeout":
298					mode = in.Mode
299				default:
300					http.Error(w, "unknown mode", 400)
301					return
302				}
303			}
304			json.NewEncoder(w).Encode(map[string]any{"mode": mode})
305		})
306		m.HandleFunc("/admin/records", func(w http.ResponseWriter, r *http.Request) {
307			mu.Lock()
308			defer mu.Unlock()
309			if r.Method == "DELETE" {
310				records = []map[string]any{}
311			}
312			json.NewEncoder(w).Encode(map[string]any{"records": records})
313		})
314		m.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
315			b, _ := io.ReadAll(io.LimitReader(r.Body, 2<<20))
316			mac := hmac.New(sha256.New, []byte(secret))
317			mac.Write(b)
318			sig, e := hex.DecodeString(r.Header.Get("X-Queuelet-Signature"))
319			valid := e == nil && hmac.Equal(sig, mac.Sum(nil))
320			mu.Lock()
321			current := mode
322			status := 200
323			if current == "500" {
324				status = 500
325			}
326			var body any
327			if json.Unmarshal(b, &body) != nil {
328				body = string(b)
329			}
330			records = append(records, map[string]any{"at": time.Now(), "body": body, "raw_body": string(b), "signature_valid": valid, "status": status})
331			mu.Unlock()
332			if !valid {
333				log.Printf("signature did not verify")
334			}
335			if current == "slow" {
336				time.Sleep(3 * time.Second)
337			}
338			if current == "timeout" {
339				time.Sleep(10 * time.Second)
340			}
341			w.Header().Set("Content-Type", "application/json")
342			w.WriteHeader(status)
343			io.WriteString(w, `{"ok":true}`)
344		})
345		log.Fatal(http.ListenAndServe(":8201", m))
346	}

