243			}
244			req.Header.Set("Content-Type", "application/json")
245			req.Header.Set("X-Queuelet-Signature", hex.EncodeToString(mac.Sum(nil)))
246			resp, e := (&http.Client{Timeout: 2 * time.Second}).Do(req)
247			if e != nil {
