 19	}
 20	func run(args []string) error {
 21		if len(args) == 0 {
 22			return fmt.Errorf("usage: qctl queue|enqueue|jobs|job|worker|schedule|stats")
 23		}
 24		c := client.Env()
 25		opts := map[string]string{}
 26		pos := []string{}
 27		for i := 0; i < len(args); i++ {
 28			if strings.HasPrefix(args[i], "--") {
 29				key := strings.TrimPrefix(args[i], "--")
 30				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "--") {
 31					i++
 32					opts[key] = args[i]
 33				} else {
 34					opts[key] = "true"
 35				}
 36			} else {
 37				pos = append(pos, args[i])
 38			}
 39		}
 40		p := func(i int) string {
 41			if i < len(pos) {
 42				return pos[i]
 43			}
 44			return ""
 45		}
 46		method, path := "GET", ""
 47		var data any
 48		jsonOpt := func(key string) any {
 49			var v any
 50			if raw := opts[key]; raw != "" {
 51				json.Unmarshal([]byte(raw), &v)
 52			}
 53			return v
 54		}
 55		integer := func(key string, fallback int) int {
 56			n, e := strconv.Atoi(opts[key])
 57			if e != nil {
 58				return fallback
 59			}
 60			return n
 61		}
 62		body := func() map[string]any {
 63			if v, ok := jsonOpt("json").(map[string]any); ok {
 64				return v
 65			}
 66			return map[string]any{}
