 78					v["lease_seconds"] = integer("lease-seconds", 30)
 79				}
 80				if opts["max-attempts"] != "" {
 81					v["max_attempts"] = integer("max-attempts", 3)
 82				}
 83				data = v
 84			case "get", "rm", "pause", "resume", "purge", "patch":
 85				path += "/" + url.PathEscape(p(2))
 86				switch p(1) {
 87				case "rm":
 88					method = "DELETE"
 89				case "patch":
 90					method = "PATCH"
 91					data = body()
 92				case "pause", "resume", "purge":
 93					method = "POST"
 94					path += "/" + p(1)
 95				}
 96			default:
 97				return fmt.Errorf("unknown queue verb")
 98			}
