100			method = "POST"
101			path = "/v1/queues/" + url.PathEscape(p(1)) + "/jobs"
102			v := body()
103			v["kind"] = opts["kind"]
104			if v["kind"] == "" {
105				v["kind"] = "echo"
106			}
107			if opts["payload"] != "" {
108				v["payload"] = jsonOpt("payload")
109			}
110			v["priority"] = integer("priority", 5)
111			if opts["delay"] != "" {
112				v["delay_seconds"] = integer("delay", 0)
113			}
114			if opts["run-at"] != "" {
115				v["run_at"] = opts["run-at"]
116			}
117			if opts["max-attempts"] != "" {
118				v["max_attempts"] = integer("max-attempts", 3)
119			}
120			if opts["idempotency-key"] != "" {
121				v["idempotency_key"] = opts["idempotency-key"]
122			}
123			data = v
