126			path = "/v1/queues/" + url.PathEscape(p(1)) + "/jobs:batch"
127			data = body()
128		case "jobs":
129			path = "/v1/queues/" + url.PathEscape(p(2)) + "/jobs"
130			query := url.Values{}
131			for _, key := range []string{"state", "kind", "limit", "cursor"} {
132				if opts[key] != "" {
133					query.Set(key, opts[key])
134				}
135			}
136			path += "?" + query.Encode()
137		case "job":
138			path = "/v1/jobs/" + p(2)
139			switch p(1) {
140			case "get":
141			case "attempts":
142				path += "/attempts"
143			case "rm":
144				method = "DELETE"
145			case "cancel", "retry", "ack", "nack", "heartbeat":
146				method = "POST"
