148				v := body()
149				if opts["lease-token"] != "" {
150					v["lease_token"] = opts["lease-token"]
151				}
152				if opts["result"] != "" {
153					v["result"] = jsonOpt("result")
154				}
155				if opts["error"] != "" {
156					v["error"] = opts["error"]
157				}
158				if opts["extend-seconds"] != "" {
159					v["extend_seconds"] = integer("extend-seconds", 30)
160				}
161				data = v
162			default:
163				return fmt.Errorf("unknown job verb")
164			}
165		case "worker":
166			if p(1) == "run" {
167				kinds := opts["kinds"]
168				if kinds == "" {
169					kinds = "echo,sleep,fail,crash,http"
170				}
171				return worker.Run(context.Background(), c, "qctl-worker", p(2), strings.Split(kinds, ","))
172			}
173			path = "/v1/workers"
174			switch p(1) {
175			case "create":
176				method = "POST"
177				kinds := opts["kinds"]
178				if kinds == "" {
179					kinds = "echo"
180				}
181				data = map[string]any{"name": p(2), "kinds": strings.Split(kinds, ",")}
182			case "rm":
183				method = "DELETE"
184				path += "/" + p(2)
185			default:
186				return fmt.Errorf("unknown worker verb")
187			}
188		case "lease":
189			method = "POST"
190			path = "/v1/queues/" + p(1) + "/lease"
191			data = map[string]any{"worker_id": integer("worker-id", 0), "max_jobs": integer("max-jobs", 1)}
192		case "schedule":
193			path = "/v1/schedules"
194			switch p(1) {
195			case "ls":
196			case "create":
197				method = "POST"
198				data = body()
199			case "get", "rm", "patch", "run":
200				path += "/" + p(2)
201				switch p(1) {
202				case "rm":
203					method = "DELETE"
204				case "patch":
205					method = "PATCH"
206					data = body()
207				case "run":
208					method = "POST"
209					path += "/run"
210				}
211			default:
212				return fmt.Errorf("unknown schedule verb")
213			}
214		case "stats":
215			path = "/v1/queues/" + p(1) + "/stats"
216			if opts["namespace"] != "" {
217				path = "/v1/namespaces/" + opts["namespace"] + "/stats"
218			}
219		default:
220			return fmt.Errorf("unknown command %s", p(0))
221		}
222		b, status, e := c.Do(method, path, data)
223		if e != nil {
224			return e
225		}
226		if status >= 400 {
227			return fmt.Errorf("HTTP %d: %s", status, b)
228		}
229		if len(b) > 0 {
230			var v any
231			if json.Unmarshal(b, &v) == nil {
232				out, _ := json.MarshalIndent(v, "", "  ")
233				fmt.Println(string(out))
234			} else {
235				fmt.Print(string(b))
236			}
237		}
238		return nil
239	}
240	package client
241	
242	import (
243		"bytes"
244		"encoding/json"
245		"fmt"
246		"io"
247		"net/http"
248		"os"
249		"time"
250	)
251	
252	type Client struct{ URL, Key string }
253	
254	func Env() *Client {
255		url := os.Getenv("QUEUELET_URL")
256		if url == "" {
257			url = "http://localhost:18200"
258		}
259		key := os.Getenv("QUEUELET_KEY")
260		if key == "" {
261			key = "acme-key"
262		}
263		return &Client{url, key}
264	}
265	func (c *Client) Do(method, path string, data any) ([]byte, int, error) {
266		var body io.Reader
267		if data != nil {
268			b, e := json.Marshal(data)
269			if e != nil {
270				return nil, 0, e
271			}
272			body = bytes.NewReader(b)
273		}
274		req, e := http.NewRequest(method, c.URL+path, body)
275		if e != nil {
276			return nil, 0, e
277		}
278		req.Header.Set("Authorization", "Bearer "+c.Key)
279		req.Header.Set("Content-Type", "application/json")
280		resp, e := (&http.Client{Timeout: 15 * time.Second}).Do(req)
281		if e != nil {
282			return nil, 0, e
283		}
284		defer resp.Body.Close()
285		b, e := io.ReadAll(resp.Body)
286		return b, resp.StatusCode, e
287	}
288	func (c *Client) JSON(method, path string, data, out any) error {
289		b, status, e := c.Do(method, path, data)
290		if e != nil {
291			return e
292		}
293		if status >= 400 {
294			return fmt.Errorf("HTTP %d: %s", status, b)
295		}
296		return json.Unmarshal(b, out)
297	}

