252	type Client struct{ URL, Key string }
253	
254	func Env() *Client {
255		url := os.Getenv("QUEUELET_URL")
256		if url == "" {
257			url = "http://localhost:18200"
258		}
259		key := os.Getenv("QUEUELET_KEY")
260		if key == "" {
261			key = "acme-key"
262		}
263		return &Client{url, key}
264	}
265	func (c *Client) Do(method, path string, data any) ([]byte, int, error) {
266		var body io.Reader
267		if data != nil {
268			b, e := json.Marshal(data)
269			if e != nil {
270				return nil, 0, e
271			}
272			body = bytes.NewReader(b)
273		}
274		req, e := http.NewRequest(method, c.URL+path, body)
275		if e != nil {
276			return nil, 0, e
277		}
278		req.Header.Set("Authorization", "Bearer "+c.Key)
279		req.Header.Set("Content-Type", "application/json")
280		resp, e := (&http.Client{Timeout: 15 * time.Second}).Do(req)
281		if e != nil {
282			return nil, 0, e
283		}
284		defer resp.Body.Close()
285		b, e := io.ReadAll(resp.Body)
286		return b, resp.StatusCode, e
287	}
288	func (c *Client) JSON(method, path string, data, out any) error {
289		b, status, e := c.Do(method, path, data)
290		if e != nil {
291			return e
292		}
293		if status >= 400 {
294			return fmt.Errorf("HTTP %d: %s", status, b)
295		}
